{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Isotretinoin, a retinoid closely related to the query scaffold, has a systemic bioavailability of 40%, supporting F >= 20% for retinoid-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Acitretin, another retinoid, has an absolute oral bioavailability of approximately 60% (range 36-95%), directly showing that lipophilic retinoids can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide amide motif, has an absolute oral bioavailability of about 82%, indicating that the phenolic amide group is compatible with high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Lutein, a highly lipophilic polyene, reached 55% oral bioavailability in a human study, supporting that very lipophilic conjugated molecules can be absorbed sufficiently to meet the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "13-cis retinoic acid was reported to have low absolute bioavailability with significant gut degradation, a contradictory observation, but this is formulation-dependent and outweighed by the 40% systemic availability reported for the same drug.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, a retinoid p-hydroxyanilide. The closest retinoid analogues (isotretinoin, acitretin, ATRA) have oral bioavailability values of 40-60%, all above the 20% threshold, and the p-hydroxyanilide moiety is associated with high bioavailability in paracetamol. Although some retinoid formulations show low/erratic absorption, the weight of direct retinoid and phenolic anilide evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide itself.",
    "No intravenous comparator data for fenretinide are available in the evidence.",
    "Formulation and food effects on fenretinide absorption are not specified.",
    "Extent of first-pass metabolism, especially phenol glucuronidation, is not directly quantified."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C43", "C07", "C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "retinoid"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C03"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "p-hydroxyanilide"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C10"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "retinoid low-bioavailability formulation"
    }
  ],
  "revision_action": "initial"
}

